javascript:(async () => {
  // ============================
  // BOOKMARKLET: TEST 01 — Click & Input (Screen 1)
  // ============================

  // --- HELPER FUNCTIONS ---
  const sleep = ms => new Promise(r => setTimeout(r, ms));

  const _qsel = sel => (sel.startsWith('/') || sel.startsWith('('))
    ? document.evaluate(sel, document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue
    : document.querySelector(sel);

  const getEl = (sel, timeout = 5000) => new Promise((res, rej) => {
    const el = _qsel(sel);
    if (el) return res(el);
    const obs = new MutationObserver(() => {
      const found = _qsel(sel);
      if (found) { obs.disconnect(); res(found); }
    });
    obs.observe(document.body, { childList: true, subtree: true });
    setTimeout(() => { obs.disconnect(); rej(new Error(`Timeout: ${sel}`)); }, timeout);
  });

  const setInput = (el, value) => {
    el.focus();
    let nv = null, p = Object.getPrototypeOf(el);
    while (p && p !== Object.prototype) {
      const d = Object.getOwnPropertyDescriptor(p, 'value');
      if (d?.set) { nv = d.set; break; }
      p = Object.getPrototypeOf(p);
    }
    if (nv) nv.call(el, value); else el.value = value;
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
  };

  const _findChild = (parent, cond) => {
    const _fbRe = /^\{fallback:(.+)\}$/;
    const _fbField = ['valueEquals','textContains','idContains','classContains','typeEquals'].find(f => cond[f] != null && _fbRe.test(String(cond[f])));
    const _fbVals  = _fbField ? String(cond[_fbField]).match(_fbRe)[1].split('|').map(s=>s.trim()) : null;
    const _tryFind = (c, blankField) => {
      const mode = c.matchMode || 'any';
      const norm = s => (s == null ? '' : String(s).trim().toLowerCase());
      const checks = [];
      if (c.valueEquals   != null && c.valueEquals   !== '') checks.push(el => el.value !== undefined && String(el.value) === String(c.valueEquals));
      if (c.textContains  != null && c.textContains  !== '') { const n = norm(c.textContains);  checks.push(el => norm(el.textContent).includes(n)); }
      if (c.idContains    != null && c.idContains    !== '') { const n = norm(c.idContains);    checks.push(el => norm(el.id).includes(n)); }
      if (c.classContains != null && c.classContains !== '') { const n = norm(c.classContains); checks.push(el => norm(el.className).includes(n)); }
      if (c.typeEquals    != null && c.typeEquals    !== '') checks.push(el => (c.typeEquals === 'select' ? el.tagName === 'SELECT' : el.type === c.typeEquals));
      if (blankField) checks.push(el => {
        if (blankField === 'valueEquals')   return el.value !== undefined && String(el.value) === '';
        if (blankField === 'textContains')  return norm(el.textContent) === '';
        if (blankField === 'idContains')    return !el.id;
        if (blankField === 'classContains') return norm(el.getAttribute('class')) === '';
        return !el.getAttribute('type');
      });
      if (!checks.length) return null;
      const test = mode === 'all' ? el => checks.every(fn => fn(el)) : el => checks.some(fn => fn(el));
      const first = (root) => {
        const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT);
        for (let node = walker.nextNode(); node; node = walker.nextNode()) { if (test(node)) return node; }
        return null;
      };
      let hit = first(parent);
      if (hit && c.textContains != null && c.textContains !== '') { for (let inner = first(hit); inner; inner = first(hit)) hit = inner; }
      return hit;
    };
    if (_fbField && _fbVals) {
      for (const _fv of _fbVals) { const el = _tryFind({...cond, [_fbField]: _fv}, _fv === '' ? _fbField : null); if (el) return el; }
      return null;
    }
    return _tryFind(cond);
  };

  // --- MAIN FLOW ---
  try {

    // Step 1: script — Go to Screen 1
    await (async () => {
      // [USER SCRIPT BEGIN]
      showScreen(1, document.querySelectorAll('nav button')[0])
      // [USER SCRIPT END]
    })();
    await sleep(300);

    // Step 2: wait — Wait for screen transition
    await sleep(300);

    // Step 3: input — Fill: Full name
    const _el3 = await getEl("#inputName", 5000);
    setInput(_el3, "John Doe");
    await sleep(300);

    // Step 4: input — Fill: Email
    const _el4 = await getEl("#inputEmail", 5000);
    setInput(_el4, "john@example.com");
    await sleep(300);

    // Step 5: input — Fill: Password
    const _el5 = await getEl("#inputPassword", 5000);
    setInput(_el5, "Passw0rd!");
    await sleep(300);

    // Step 6: input — Fill: Phone
    const _el6 = await getEl("#inputPhone", 5000);
    setInput(_el6, "+1 555 123 4567");
    await sleep(300);

    // Step 7: input — Fill: Message textarea
    const _el7 = await getEl("#inputMessage", 5000);
    setInput(_el7, "Hello from automation!");
    await sleep(300);

    // Step 8: input — Select: Country → Vietnam
    const _el8 = await getEl("#selectCountry", 5000);
    setInput(_el8, "vn");
    await sleep(300);

    // Step 9: input — Select: Priority → High
    const _el9 = await getEl("#selectPriority", 5000);
    setInput(_el9, "high");
    await sleep(300);

    // Step 10: click — Check: Accept terms
    const _el10 = await getEl("#chkTerms", 5000);
    _el10.click();
    await sleep(300);

    // Step 11: click — Check: Remember me
    const _el11 = await getEl("#chkRemember", 5000);
    _el11.click();
    await sleep(300);

    // Step 12: click — Radio: Select Viewer role
    const _el12 = await getEl("input[name=\"role\"][value=\"viewer\"]", 5000);
    _el12.click();
    await sleep(300);

    // Step 13: click — Click: Load Sample
    const _el13 = await getEl("#btnLoad", 5000);
    _el13.click();
    await sleep(300);

    // Step 14: wait — Wait after load
    await sleep(400);

    // Step 15: click — Click: Submit Form
    const _el15 = await getEl("#btnSubmit", 5000);
    _el15.click();
    await sleep(300);

    // Step 16: wait — Wait for form status
    await sleep(500);

    // Step 17: click — Click: Reset
    const _el17 = await getEl("#btnReset", 5000);
    _el17.click();
    await sleep(300);

    console.log('✅ Bookmarklet completed successfully.');

  } catch (err) {
    console.error('❌ Bookmarklet error:', err);
    alert('Error: ' + err.message);
  }

})();

